UPDATE TBL_REPORT_RECORD
TEMPLATE_ID = #{templateId}, REPORT_NAME = #{reportName}, REPORT_TYPE = #{reportType}, GENERATION_STATUS = #{generationStatus}, FILE_PATH = #{filePath}, FILE_SIZE = #{fileSize}, GENERATION_TIME = #{generationTime}, GENERATED_BY = #{generatedBy}, GENERATED_BY_NAME = #{generatedByName}, COMPANY_ID = #{companyId}, COMPANY_NAME = #{companyName}, DELETE_FLAG = #{deleteFlag}, REMARK = #{remark}, PERIOD_TYPE = #{periodType}, PERIOD_START_DATE = #{periodStartDate}, PERIOD_END_DATE = #{periodEndDate}, DOWNLOAD_COUNT = #{downloadCount}, UPDATED_TIME = SYSDATE
