mapper.select:
SELECT 
FROM TBL_REPORT_RECORD
WHERE DELETE_FLAG = 0

    AND REPORT_NAME LIKE '%' || #{reportName} || '%'


    AND REPORT_TYPE = #{reportType}


    AND GENERATION_STATUS = #{generationStatus}


    AND TEMPLATE_ID = #{templateId}


    AND COMPANY_ID = #{companyId}


    AND GENERATED_BY = #{generatedBy}


    AND GENERATION_TIME >= #{generationTimeStart}


    AND GENERATION_TIME <= #{generationTimeEnd}

ORDER BY GENERATION_TIME DESC

